export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const choose = (arr) => arr[(Math.random() * arr.length) | 0];
export const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
export const smoothstep = (t) => {
  t = clamp(t, 0, 1);
  return t * t * (3 - 2 * t);
};
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const roundRect = (ctx, x, y, w, h, r) => {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
};

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function pointInTriangle(px, py, ax, ay, bx, by, cx, cy) {
  const d1 = (px - bx) * (ay - by) - (ax - bx) * (py - by);
  const d2 = (px - cx) * (by - cy) - (bx - cx) * (py - cy);
  const d3 = (px - ax) * (cy - ay) - (cx - ax) * (py - ay);
  const neg = d1 < 0 || d2 < 0 || d3 < 0;
  const pos = d1 > 0 || d2 > 0 || d3 > 0;
  return !(neg && pos);
}

export function rectCircle(rect, cx, cy, cr) {
  const nx = clamp(cx, rect.x, rect.x + rect.w);
  const ny = clamp(cy, rect.y, rect.y + rect.h);
  return (cx - nx) * (cx - nx) + (cy - ny) * (cy - ny) <= cr * cr;
}

export function formatNumber(n) {
  return Math.round(n).toString();
}

export const ROMAN = ['I', 'II', 'III', 'IV'];

export function seededNoise(seed) {
  const rng = mulberry32(seed);
  const table = new Float32Array(256);
  for (let i = 0; i < 256; i++) table[i] = rng() * 2 - 1;
  return (x) => {
    const i = Math.floor(x);
    const f = x - i;
    const a = table[i & 255];
    const b = table[(i + 1) & 255];
    const t = f * f * (3 - 2 * f);
    return lerp(a, b, t);
  };
}

// Tiny procedural sound kit — no external assets.
export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.noiseBuffer = null;
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.5;
      const comp = this.ctx.createDynamicsCompressor();
      comp.threshold.value = -16;
      comp.knee.value = 20;
      comp.ratio.value = 6;
      this.master.connect(comp);
      comp.connect(this.ctx.destination);
      this.buildNoise();
    } catch {
      this.ctx = null;
    }
  }

  buildNoise() {
    const len = this.ctx.sampleRate * 1.2;
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    this.noiseBuffer = buffer;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.5, this.ctx.currentTime, 0.02);
    }
  }

  now() { return this.ctx ? this.ctx.currentTime : 0; }

  tone(freq, dur, type = 'sine', gain = 0.15, slideTo = null, delay = 0) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.04);
  }

  noise(dur, freq = 900, gain = 0.2, delay = 0, q = 0.8, type = 'lowpass') {
    if (!this.ctx || this.muted || !this.noiseBuffer) return;
    const t = this.now() + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    filter.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.05);
  }

  ui() { this.tone(520, 0.07, 'triangle', 0.06, 660); }
  select() { this.tone(430, 0.09, 'square', 0.045, 620); }

  shoot(kind = 'rocket') {
    if (kind === 'rocket') {
      this.noise(0.38, 1800, 0.24, 0, 1.3);
      this.tone(140, 0.32, 'sawtooth', 0.1, 48);
      this.tone(560, 0.12, 'square', 0.04, 180);
    } else if (kind === 'cluster') {
      this.noise(0.3, 1300, 0.2, 0, 1.1);
      this.tone(240, 0.18, 'square', 0.07, 90);
    } else {
      this.noise(0.22, 900, 0.18, 0, 0.8);
      this.tone(190, 0.16, 'triangle', 0.09, 120);
    }
  }

  explosion(big = 1) {
    this.noise(0.55 + big * 0.25, 520, 0.35, 0, 0.9);
    this.noise(0.34, 180, 0.4, 0.01, 0.7);
    this.tone(86, 0.6, 'sine', 0.34, 34);
    this.tone(52, 0.8, 'triangle', 0.22, 26, 0.03);
  }

  split() { this.tone(720, 0.12, 'square', 0.06, 1000); this.tone(980, 0.1, 'square', 0.04, 1400, 0.04); }
  build() {
    this.tone(170, 0.07, 'square', 0.08, 130);
    this.noise(0.11, 2400, 0.12, 0.02, 1.2, 'highpass');
    this.tone(420, 0.1, 'triangle', 0.05, 550, 0.05);
  }
  invalid() { this.tone(150, 0.14, 'square', 0.06, 110); }
  jump() { this.tone(330, 0.13, 'sine', 0.07, 540); }
  hurt() { this.tone(220, 0.18, 'sawtooth', 0.08, 90); this.noise(0.12, 600, 0.09); }
  llama() {
    this.tone(660, 0.12, 'square', 0.06, 880);
    this.tone(880, 0.12, 'square', 0.05, 1180, 0.09);
    this.tone(1180, 0.18, 'triangle', 0.05, 1500, 0.18);
  }
  turn(player) {
    if (player) {
      this.tone(392, 0.13, 'triangle', 0.06, 392);
      this.tone(587, 0.22, 'triangle', 0.06, 587, 0.12);
    } else {
      this.tone(294, 0.14, 'triangle', 0.05, 294);
      this.tone(220, 0.22, 'triangle', 0.05, 220, 0.12);
    }
  }
  win() {
    const notes = [523, 659, 784, 1047, 1319];
    notes.forEach((n, i) => this.tone(n, 0.3, 'triangle', 0.08, n, i * 0.11));
    this.tone(1568, 0.6, 'sine', 0.07, 1568, 0.55);
  }
  lose() {
    const notes = [392, 349, 294, 220];
    notes.forEach((n, i) => this.tone(n, 0.36, 'triangle', 0.075, n * 0.98, i * 0.16));
  }
  tick() { this.tone(880, 0.04, 'square', 0.03, 880); }
}

import { clamp, lerp, mulberry32, seededNoise, smoothstep } from './utils.js';

function padWeight(x, center, radius) {
  return smoothstep(1 - Math.abs(x - center) / radius);
}

export class Terrain {
  constructor(w, h, seed = 7) {
    this.w = w;
    this.h = h;
    this.seed = seed;
    this.canvas = document.createElement('canvas');
    this.canvas.width = w;
    this.canvas.height = h;
    this.ctx = this.canvas.getContext('2d');
    this.scars = document.createElement('canvas');
    this.scars.width = w;
    this.scars.height = h;
    this.sctx = this.scars.getContext('2d');
    this.mask = new Uint8Array(w * h);
    this.islands = [];
    this.generate();
  }

  generate() {
    const { w, h, ctx } = this;
    const rng = mulberry32(this.seed);
    const noise = seededNoise(this.seed * 13 + 3);
    const noise2 = seededNoise(this.seed * 31 + 9);
    const heights = new Float32Array(w);

    for (let x = 0; x < w; x++) {
      let y = h * 0.675;
      y -= noise(x * 0.0032) * 58;
      y -= noise2(x * 0.0091 + 40) * 24;
      y -= noise(x * 0.017 + 100) * 9;
      // A tall mid-left mesa and a central valley: instant cover and verticality.
      y -= Math.exp(-Math.pow((x - w * 0.335) / (w * 0.062), 2)) * h * 0.19;
      y += Math.exp(-Math.pow((x - w * 0.475) / (w * 0.075), 2)) * h * 0.085;
      y -= Math.exp(-Math.pow((x - w * 0.675) / (w * 0.085), 2)) * h * 0.095;
      y -= Math.exp(-Math.pow((x - w * 0.845) / (w * 0.055), 2)) * h * 0.05;
      // Flat spawn benches on both sides.
      y = lerp(y, h * 0.675, padWeight(x, 158, 158));
      y = lerp(y, h * 0.675, padWeight(x, w - 158, 158));
      y = clamp(y, h * 0.4, h * 0.82);
      heights[x] = y;
    }
    this.heights = heights;

    ctx.clearRect(0, 0, w, h);

    // ---------- dirt body ----------
    ctx.beginPath();
    ctx.moveTo(0, h);
    ctx.lineTo(0, heights[0]);
    for (let x = 1; x < w; x++) {
      const prev = heights[x - 1];
      const cur = heights[x];
      ctx.lineTo(x, (prev + cur) / 2);
    }
    ctx.lineTo(w, heights[w - 1]);
    ctx.lineTo(w, h);
    ctx.closePath();

    const dirt = ctx.createLinearGradient(0, h * 0.35, 0, h);
    dirt.addColorStop(0, '#7b4a2c');
    dirt.addColorStop(0.32, '#633a24');
    dirt.addColorStop(0.72, '#43241b');
    dirt.addColorStop(1, '#2a1513');
    ctx.fillStyle = dirt;
    ctx.fill();

    ctx.save();
    ctx.clip();

    // rock strata
    for (let i = 0; i < 16; i++) {
      const sy = h * 0.46 + rng() * h * 0.5;
      ctx.beginPath();
      ctx.moveTo(0, sy);
      for (let x = 0; x <= w; x += 90) {
        ctx.lineTo(x, sy + Math.sin(x * 0.01 + i) * 9 + rng() * 3);
      }
      ctx.lineWidth = 1.5 + rng() * 2.5;
      ctx.strokeStyle = i % 3 === 0 ? 'rgba(20, 10, 8, 0.28)' : 'rgba(160, 100, 62, 0.13)';
      ctx.stroke();
    }

    // pebbles and roots
    for (let i = 0; i < 470; i++) {
      const x = rng() * w;
      const top = heights[Math.floor(x)] || h * 0.7;
      const y = top + 26 + Math.pow(rng(), 0.7) * (h - top);
      if (y > h - 4) continue;
      const r = 0.7 + rng() * (rng() > 0.9 ? 7 : 2.4);
      ctx.beginPath();
      ctx.ellipse(x, y, r * (0.7 + rng()), r, rng() * Math.PI, 0, Math.PI * 2);
      ctx.fillStyle = rng() > 0.45 ? `rgba(30, 16, 13, ${0.15 + rng() * 0.25})` : `rgba(176, 119, 74, ${0.1 + rng() * 0.2})`;
      ctx.fill();
    }

    // bottom vignette
    const bottom = ctx.createLinearGradient(0, h * 0.72, 0, h);
    bottom.addColorStop(0, 'rgba(20, 10, 12, 0)');
    bottom.addColorStop(1, 'rgba(14, 7, 12, 0.55)');
    ctx.fillStyle = bottom;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();

    // ---------- floating islands ----------
    this.islands = [
      { x: w * 0.545, y: h * 0.285, rx: w * 0.075, ry: 26, phase: 0 },
      { x: w * 0.235, y: h * 0.44, rx: w * 0.044, ry: 18, phase: 2.1 },
      { x: w * 0.79, y: h * 0.35, rx: w * 0.05, ry: 20, phase: 4.4 },
    ];
    for (const island of this.islands) this.drawIsland(island, rng);

    // ---------- grass edge ----------
    const tracePath = () => {
      ctx.beginPath();
      ctx.moveTo(0, heights[0] + 4);
      for (let x = 1; x < w; x++) ctx.lineTo(x, heights[x] + 4);
    };
    tracePath();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#28431f';
    ctx.lineWidth = 22;
    ctx.stroke();
    tracePath();
    ctx.strokeStyle = '#4f8f32';
    ctx.lineWidth = 16;
    ctx.stroke();
    tracePath();
    ctx.strokeStyle = '#82c344';
    ctx.lineWidth = 9;
    ctx.stroke();
    tracePath();
    ctx.strokeStyle = '#b9ee64';
    ctx.lineWidth = 3.2;
    ctx.stroke();

    // grass blades
    for (let i = 0; i < 220; i++) {
      const x = rng() * w;
      const y = heights[Math.floor(x)];
      if (rng() > 0.55) continue;
      const tall = 3 + rng() * 7;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.quadraticCurveTo(x + (rng() - 0.5) * 5, y - tall * 0.6, x + (rng() - 0.5) * 9, y - tall);
      ctx.strokeStyle = rng() > 0.5 ? 'rgba(165, 230, 92, 0.85)' : 'rgba(95, 154, 53, 0.9)';
      ctx.lineWidth = 1.4;
      ctx.stroke();
    }

    // a few chunky stones on the surface
    for (let i = 0; i < 26; i++) {
      const x = 40 + rng() * (w - 80);
      const y = heights[Math.floor(x)] + 4;
      if (rng() > 0.5) continue;
      const r = 5 + rng() * 11;
      ctx.beginPath();
      ctx.ellipse(x, y, r, r * 0.6, rng() * 3, 0, Math.PI * 2);
      ctx.fillStyle = '#5a4a42';
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(x - r * 0.2, y - r * 0.3, r * 0.65, r * 0.32, 0, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(160, 142, 120, 0.4)';
      ctx.fill();
    }

    this.buildMask();
  }

  drawIsland(island, rng) {
    const { ctx } = this;
    const { x, y, rx, ry } = island;
    // dangling rocky underside
    ctx.beginPath();
    ctx.moveTo(x - rx, y);
    ctx.quadraticCurveTo(x - rx * 0.7, y + ry + 20, x - rx * 0.25, y + ry + 34);
    ctx.lineTo(x + rx * 0.1, y + ry + 20);
    ctx.quadraticCurveTo(x + rx * 0.55, y + ry + 46, x + rx * 0.72, y + ry + 10);
    ctx.quadraticCurveTo(x + rx, y + ry + 4, x + rx, y);
    ctx.closePath();
    const g = ctx.createLinearGradient(0, y - ry, 0, y + ry + 40);
    g.addColorStop(0, '#6e4028');
    g.addColorStop(1, '#301a18');
    ctx.fillStyle = g;
    ctx.fill();

    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#5d3522';
    ctx.fill();

    ctx.beginPath();
    ctx.ellipse(x, y - 2, rx, ry * 0.78, 0, Math.PI, 0);
    ctx.fillStyle = '#497f31';
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(x, y - 5, rx * 0.94, ry * 0.56, 0, Math.PI, 0);
    ctx.fillStyle = '#7dbb45';
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(x, y - 8, rx * 0.8, ry * 0.28, 0, Math.PI, 0);
    ctx.fillStyle = '#b5e966';
    ctx.fill();

    for (let i = 0; i < 5; i++) {
      const bx = x - rx * 0.6 + rng() * rx * 1.2;
      const by = y + 2 + rng() * ry * 0.6;
      ctx.beginPath();
      ctx.ellipse(bx, by, 1 + rng() * 2.4, 1 + rng() * 1.6, 0, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(30, 16, 13, 0.4)';
      ctx.fill();
    }
    // vines
    for (let i = 0; i < 3; i++) {
      const vx = x - rx * 0.5 + rng() * rx;
      ctx.beginPath();
      ctx.moveTo(vx, y + ry * 0.55);
      ctx.quadraticCurveTo(vx + 6, y + ry + 14, vx - 4, y + ry + 26 + rng() * 20);
      ctx.strokeStyle = 'rgba(78, 128, 48, 0.8)';
      ctx.lineWidth = 1.6;
      ctx.stroke();
    }
  }

  buildMask() {
    const { ctx, w, h, mask } = this;
    const data = ctx.getImageData(0, 0, w, h).data;
    mask.fill(0);
    for (let i = 0, p = 0; i < data.length; i += 4, p++) {
      mask[p] = data[i + 3] > 30 ? 1 : 0;
    }
  }

  solidAt(x, y) {
    const ix = x | 0;
    const iy = y | 0;
    if (ix < 0 || ix >= this.w || iy < 0 || iy >= this.h) return false;
    return this.mask[iy * this.w + ix] === 1;
  }

  topAt(x) {
    const ix = clamp(x | 0, 0, this.w - 1);
    for (let y = 0; y < this.h; y++) {
      if (this.mask[y * this.w + ix]) return y;
    }
    return this.h;
  }

  surfaceBelow(x, fromY, maxY = this.h) {
    const ix = clamp(x | 0, 0, this.w - 1);
    const start = clamp(Math.floor(fromY), 0, this.h - 1);
    const end = clamp(Math.floor(maxY), 0, this.h - 1);
    for (let y = start; y <= end; y++) {
      if (this.mask[y * this.w + ix]) return y;
    }
    return null;
  }

  carve(x, y, radius) {
    const { ctx, sctx, w, h } = this;
    const r = Math.max(8, radius);
    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';
    const g = ctx.createRadialGradient(x, y, r * 0.45, x, y, r);
    g.addColorStop(0, 'rgba(0,0,0,1)');
    g.addColorStop(0.72, 'rgba(0,0,0,0.96)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // Persistent scorch ring around the crater.
    sctx.save();
    const sg = sctx.createRadialGradient(x, y, r * 0.5, x, y, r * 1.18);
    sg.addColorStop(0, 'rgba(30, 16, 12, 0)');
    sg.addColorStop(0.62, 'rgba(30, 16, 12, 0.18)');
    sg.addColorStop(0.82, 'rgba(18, 9, 9, 0.38)');
    sg.addColorStop(1, 'rgba(10, 5, 5, 0)');
    sctx.fillStyle = sg;
    sctx.beginPath();
    sctx.arc(x, y, r * 1.2, 0, Math.PI * 2);
    sctx.fill();
    sctx.restore();

    const rr = r * 0.93;
    const minX = Math.max(0, Math.floor(x - rr));
    const maxX = Math.min(w - 1, Math.ceil(x + rr));
    const minY = Math.max(0, Math.floor(y - rr));
    const maxY = Math.min(h - 1, Math.ceil(y + rr));
    const rr2 = rr * rr;
    for (let py = minY; py <= maxY; py++) {
      const dy = py - y;
      const row = py * w;
      for (let px = minX; px <= maxX; px++) {
        const dx = px - x;
        if (dx * dx + dy * dy <= rr2) this.mask[row + px] = 0;
      }
    }
  }

  draw(ctx) {
    ctx.drawImage(this.canvas, 0, 0);
    ctx.drawImage(this.scars, 0, 0);
  }
}

