  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = '#e88cdb';
  ctx.beginPath();
  ctx.ellipse(-20, -21, 9, 8, 0, 0, TAU);
  ctx.fill();
  ctx.stroke();
  // ears
  ctx.fillStyle = '#f39ce5';
