(async () => {
  mkdirSync('/tmp/opencode/shots', { recursive: true });
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') console.log('CONSOLE', m.type(), m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(1500);
  console.log('state before', await page.evaluate(() => window.__fortArtillery?.state));
  console.log('btn box', await page.locator('#playBtn').boundingBox());
  await page.screenshot({ path: '/tmp/opencode/shots/start.png' });
  await page.evaluate(() => document.getElementById('playBtn').click());
  await page.waitForTimeout(1800);
  console.log('state after', await page.evaluate(() => ({
    state: window.__fortArtillery?.state,
    active: window.__fortArtillery?.active?.name,
    cam: [window.__fortArtillery?.camX, window.__fortArtillery?.camY],
    view: window.__fortArtillery?.view,
    worms: window.__fortArtillery?.worms.map(w => [w.name, Math.round(w.x), Math.round(w.y), w.health, w.grounded]),
    terrain: !!window.__fortArtillery?.terrain,
  })));
  await page.screenshot({ path: '/tmp/opencode/shots/game.png' });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

