const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  page.on('console', m => console.log('CONSOLE', m.type(), m.text()));
  const t0 = Date.now();
  await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
  console.log('loaded in', Date.now() - t0);
  await page.waitForTimeout(1000);
  const info = await page.evaluate(() => {
    const el = document.getElementById('playBtn');
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    const hit = document.elementFromPoint(cx, cy);
    return {
      state: window.__fortArtillery?.state,
      rect: { x: r.x, y: r.y, w: r.width, h: r.height },
      hitTag: hit?.tagName, hitId: hit?.id, hitClass: hit?.className,
      contained: el.contains(hit),
      visible: !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length),
      opacity: getComputedStyle(el).opacity,
      animations: document.getAnimations().map(a => ({ name: a.animationName, state: a.playState, target: a.effect?.target?.id || a.effect?.target?.className })),
    };
  });
  console.log('info', JSON.stringify(info, null, 2));
  const loc = page.locator('#playBtn');
  console.log('isVisible', await loc.isVisible(), 'enabled', await loc.isEnabled());
  for (const t of [500, 1000, 2000]) {
    const s = Date.now();
    try {
      await loc.click({ trial: true, timeout: t });
      console.log('trial click ok in', Date.now() - s, 'with timeout', t);
      break;
    } catch (e) {
      console.log('trial click failed in', Date.now() - s, 'with timeout', t, e.name, e.message.split('\n').slice(0, 4).join(' | '));
    }
  }
  const s2 = Date.now();
  try {
    await loc.click({ timeout: 5000, noWaitAfter: true });
    console.log('real click ok in', Date.now() - s2);
  } catch (e) {
    console.log('real click failed in', Date.now() - s2, e.name, e.message.split('\n').slice(0, 6).join(' | '));
  }
  await page.waitForTimeout(500);
  const after = await page.evaluate(() => ({ state: window.__fortArtillery?.state, active: window.__fortArtillery?.active?.name }));
  console.log('after', after);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

