const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height } });
    page.on('pageerror', e => console.log('PAGEERROR:', e.message));
    const t0 = Date.now();
    await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
    await page.locator('body').waitFor({ state: 'visible' });
    await page.waitForFunction(() => document.fonts.status === 'loaded');
    console.log(name, 'loaded in', Date.now() - t0);
    const candidate = page.locator('button, input[type="button"], input[type="submit"], [role="button"]');
    const matches = [];
    for (const control of await candidate.all()) {
      if (!await control.isVisible() || !await control.isEnabled()) continue;
      const eligible = await control.evaluate((element) => {
        if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false;
        const label = element.getAttribute('aria-label') || element.value || element.textContent || '';
        return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim());
      });
      if (eligible) matches.push(control);
    }
    console.log(name, 'matches', matches.length);
    if (matches.length === 1) {
      for (let i = 0; i < 3; i++) {
        const s = Date.now();
        try {
          await matches[0].click({ trial: true, timeout: 2000 });
          console.log(name, 'trial ok after', Date.now() - s);
          break;
        } catch (e) {
          console.log(name, 'trial fail after', Date.now() - s, e.message.split('\n').slice(0, 6).join(' | '));
        }
      }
      const s = Date.now();
      try {
        await matches[0].click({ timeout: 2000, noWaitAfter: true });
        console.log(name, 'click ok after', Date.now() - s);
      } catch (e) {
        console.log(name, 'click fail after', Date.now() - s, e.message.split('\n').slice(0, 6).join(' | '));
      }
    }
    await page.waitForTimeout(1000);
    console.log(name, 'state', await page.evaluate(() => window.__fortArtillery?.state));
    await page.screenshot({ path: `/tmp/opencode/shots/diag-${name}.png`, timeout: 30000 });
    console.log(name, 'screenshot done', Date.now() - t0);
    await page.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

