298:   ctx.globalAlpha = 0.85;
299:   if (b.type === 'ramp') {
300:     if (b.dir === 1) ctx.fillRect(b.x + b.w * 0.62, b.y + 6, b.w * 0.38, 3.5);
301:     else ctx.fillRect(b.x, b.y + 6, b.w * 0.38, 3.5);
302:   } else {
303:     ctx.fillRect(b.x + 2, b.y + 2, b.w - 4, 3.5);
304:   }
305:   ctx.globalAlpha = 1;
306:   ctx.restore();
307: 
308:   // nails
309:   if (b.type !== 'floor') {
310:     ctx.fillStyle = 'rgba(60, 38, 22, 0.75)';
311:     for (const [nx, ny] of [[b.x + 8, b.y + 8], [b.x + b.w - 8, b.y + 8], [b.x + 8, b.y + b.h - 8], [b.x + b.w - 8, b.y + b.h - 8]]) {
312:       ctx.beginPath();
313:       ctx.arc(nx, ny, 1.7, 0, TAU);
314:       ctx.fill();
315:     }
316:   }
317: 
318:   // build sparkle
319:   if (age < 0.4) {
320:     const a = 1 - age / 0.4;
321:     ctx.strokeStyle = `rgba(255, 245, 190, ${a * 0.9})`;
322:     ctx.lineWidth = 2;
323:     ctx.beginPath();
324:     ctx.arc(cx, cy, b.w * 0.6 + age * 40, 0, TAU);
325:     ctx.stroke();
326:   }
327: 
328:   ctx.restore();
329: 
330:   if (b.hp < b.maxHp) {
331:     const w = b.w * 0.62;
332:     const hx = cx - w / 2;
333:     const hy = b.y - 12;
334:     ctx.fillStyle = 'rgba(0,0,0,0.55)';
335:     roundRect(ctx, hx, hy, w, 5, 2.5);
336:     ctx.fill();
337:     ctx.fillStyle = b.hp / b.maxHp > 0.4 ? '#a8ef4f' : '#ffb35c';
338:     roundRect(ctx, hx, hy, w * (b.hp / b.maxHp), 5, 2.5);
339:     ctx.fill();
340:   }
341: }
