408:   ctx.stroke();
409:   ctx.fillStyle = '#e88cdb';
410:   ctx.beginPath();
411:   ctx.ellipse(-20, -21, 9, 8, 0, 0, TAU);
412:   ctx.fill();
413:   ctx.stroke();
414:   // ears
415:   ctx.fillStyle = '#f39ce5';
416:   ctx.beginPath();
417:   ctx.moveTo(-24, -27);
418:   ctx.lineTo(-27, -37);
