592: export function drawWorm(ctx, g, w) {
593:   if (!w.alive) return;
594:   const team = g.teams[w.team];
595:   const isActive = g.active === w && (g.state === 'aim' || g.state === 'enemy');
596:   const aimRad = (g.aim.angle * Math.PI) / 180;
597:   const face = isActive ? (Math.cos(aimRad) >= 0 ? 1 : -1) : (w.team === 0 ? 1 : -1);
598:   const bob = w.grounded ? Math.sin(g.time * 3.2 + w.phase) * 0.8 : 0;
599: 
600:   // ground shadow
601:   ctx.save();
602:   const groundY = w.y + 16 + 6;
603:   ctx.fillStyle = 'rgba(0,0,0,0.24)';
604:   ctx.beginPath();
605:   ctx.ellipse(w.x, groundY, 18, 5, 0, 0, TAU);
606:   ctx.fill();
607:   ctx.restore();
608: 
609:   // active aura
610:   if (isActive) {
611:     ctx.save();
612:     const pulse = 0.55 + Math.sin(g.time * 3.2) * 0.2;
613:     ctx.strokeStyle = team.color;
614:     ctx.globalAlpha = pulse;
615:     ctx.lineWidth = 2;
616:     ctx.setLineDash([5, 5]);
617:     ctx.beginPath();
618:     ctx.ellipse(w.x, w.y + 16 + 4, 25, 8, 0, 0, TAU);
619:     ctx.stroke();
620:     ctx.setLineDash([]);
621:     const glow = ctx.createRadialGradient(w.x, w.y, 5, w.x, w.y, 46);
622:     glow.addColorStop(0, `${team.color}22`);
623:     glow.addColorStop(1, `${team.color}00`);
624:     ctx.fillStyle = glow;
625:     ctx.beginPath();
626:     ctx.arc(w.x, w.y, 46, 0, TAU);
627:     ctx.fill();
628:     ctx.restore();
629:   }
630: 
631:   // launcher for active worm (drawn in world space)
632:   if (isActive) {
633:     ctx.save();
634:     ctx.translate(w.x, w.y - 4);
635:     ctx.rotate(-aimRad);
636:     const kick = w.recoil || 0;
637:     ctx.translate(-kick * 5, 0);
638:     const tube = ctx.createLinearGradient(0, -6, 0, 6);
639:     tube.addColorStop(0, '#6d7488');
640:     tube.addColorStop(0.5, '#444b5d');
641:     tube.addColorStop(1, '#2b3040');
642:     ctx.fillStyle = tube;
643:     roundRect(ctx, 2, -5.5, 38, 11, 4);
644:     ctx.fill();
645:     ctx.strokeStyle = '#1e2230';
646:     ctx.lineWidth = 1.8;
647:     ctx.stroke();
648:     ctx.fillStyle = '#ffb45c';
649:     roundRect(ctx, 36, -7.5, 5, 15, 2);
650:     ctx.fill();
651:     ctx.fillStyle = 'rgba(255,255,255,0.3)';
652:     roundRect(ctx, 8, -4.4, 22, 2, 1);
653:     ctx.fill();
654:     // grip
655:     ctx.fillStyle = '#2a2f3d';
656:     roundRect(ctx, 13, 4, 7, 7, 2);
657:     ctx.fill();
658:     // charge glow at the muzzle
659:     const glow = 0.4 + Math.sin(g.time * 5) * 0.15;
660:     ctx.fillStyle = `rgba(255, 209, 102, ${glow})`;
661:     ctx.beginPath();
662:     ctx.arc(43, 0, 4.5, 0, TAU);
663:     ctx.fill();
664:     ctx.restore();
665:   }
666: 
667:   // body
668:   ctx.save();
669:   ctx.translate(w.x, w.y + bob);
670:   drawBaseWorm(ctx, team.color, team.dark, team.light, w.flash || 0, face, g, w);
671:   ctx.restore();
672: 
673:   // active marker
674:   if (isActive) {
675:     const by = w.y - 48 + Math.sin(g.time * 4) * 4;
676:     ctx.fillStyle = team.color;
677:     ctx.beginPath();
678:     ctx.moveTo(w.x, by + 8);
679:     ctx.lineTo(w.x - 8, by - 2);
680:     ctx.lineTo(w.x + 8, by - 2);
681:     ctx.closePath();
682:     ctx.fill();
683:     ctx.strokeStyle = 'rgba(0,0,0,0.25)';
684:     ctx.lineWidth = 1.2;
685:     ctx.stroke();
686:   }
687: 
688:   // name + health
689:   const hpW = 42;
690:   const hpY = w.y - 31;
691:   ctx.font = '800 9px "Trebuchet MS", sans-serif';
692:   ctx.textAlign = 'center';
693:   ctx.fillStyle = isActive ? team.color : 'rgba(255,255,255,0.7)';
694:   ctx.fillText(w.name, w.x, hpY - 5);
695:   ctx.fillStyle = 'rgba(0,0,0,0.52)';
696:   roundRect(ctx, w.x - hpW / 2, hpY, hpW, 5, 2.5);
697:   ctx.fill();
698:   const ratio = clamp(w.health / w.maxHealth, 0, 1);
699:   ctx.fillStyle = ratio > 0.55 ? '#8cf07a' : ratio > 0.28 ? '#ffc35c' : '#ff6b5e';
700:   roundRect(ctx, w.x - hpW / 2, hpY, hpW * ratio, 5, 2.5);
701:   ctx.fill();
702:   if (w.health < w.maxHealth) {
703:     ctx.font = '700 8px "Trebuchet MS", sans-serif';
704:     ctx.fillStyle = 'rgba(255,255,255,0.8)';
705:     ctx.fillText(Math.ceil(w.health), w.x + hpW / 2 + 11, hpY + 5);
706:   }
707: }
