747: export function drawProjectile(ctx, g, p) {
748:   // trail
749:   if (p.trail.length > 1) {
750:     ctx.save();
751:     ctx.lineCap = 'round';
752:     for (let i = 1; i < p.trail.length; i++) {
753:       const t = i / p.trail.length;
754:       const a = t * 0.52;
755:       ctx.strokeStyle = p.cfg.trail.replace(/[\d.]+\)$/, `${a})`);
756:       ctx.lineWidth = 1 + t * 4.2;
757:       ctx.beginPath();
758:       ctx.moveTo(p.trail[i - 1].x, p.trail[i - 1].y);
759:       ctx.lineTo(p.trail[i].x, p.trail[i].y);
760:       ctx.stroke();
761:     }
762:     ctx.restore();
763:   }
764: 
765:   ctx.save();
766:   ctx.translate(p.x, p.y);
767:   if (p.cfg.id === 'rocket') {
768:     const ang = Math.atan2(p.vy, p.vx);
769:     ctx.rotate(ang);
770:     // flame
771:     const flick = 0.7 + Math.sin(g.time * 40 + p.x) * 0.3;
772:     const flame = ctx.createLinearGradient(-12, 0, -30 * flick, 0);
773:     flame.addColorStop(0, 'rgba(255, 240, 170, 0.95)');
774:     flame.addColorStop(0.5, 'rgba(255, 150, 60, 0.8)');
775:     flame.addColorStop(1, 'rgba(255, 90, 40, 0)');
776:     ctx.fillStyle = flame;
777:     ctx.beginPath();
778:     ctx.moveTo(-11, -5);
779:     ctx.lineTo(-24 * flick - 9, 0);
780:     ctx.lineTo(-11, 5);
781:     ctx.closePath();
782:     ctx.fill();
783:     // body
784:     ctx.fillStyle = '#596273';
785:     roundRect(ctx, -12, -5, 22, 10, 4);
786:     ctx.fill();
787:     ctx.strokeStyle = '#272d38';
788:     ctx.lineWidth = 1.6;
789:     ctx.stroke();
790:     ctx.fillStyle = '#ffd166';
791:     ctx.beginPath();
792:     ctx.moveTo(10, -5);
793:     ctx.lineTo(17, 0);
794:     ctx.lineTo(10, 5);
795:     ctx.closePath();
796:     ctx.fill();
797:     ctx.fillStyle = '#3c4350';
798:     ctx.beginPath();
799:     ctx.moveTo(-9, -5);
800:     ctx.lineTo(-14, -10);
801:     ctx.lineTo(-4, -5);
802:     ctx.closePath();
803:     ctx.fill();
804:     ctx.beginPath();
805:     ctx.moveTo(-9, 5);
806:     ctx.lineTo(-14, 10);
807:     ctx.lineTo(-4, 5);
808:     ctx.closePath();
809:     ctx.fill();
810:   } else if (p.cfg.id === 'grenade') {
811:     ctx.rotate(p.age * 9);
812:     ctx.fillStyle = '#3f5b34';
813:     ctx.beginPath();
814:     ctx.arc(0, 0, 7.5, 0, TAU);
815:     ctx.fill();
816:     ctx.strokeStyle = '#20301c';
817:     ctx.lineWidth = 1.8;
818:     ctx.stroke();
819:     ctx.fillStyle = '#7ea34f';
820:     roundRect(ctx, -2, -9, 4, 4, 1);
821:     ctx.fill();
822:     ctx.strokeStyle = 'rgba(255,255,255,0.32)';
823:     ctx.lineWidth = 1.4;
824:     ctx.beginPath();
825:     ctx.arc(-2, -2, 3.2, Math.PI * 0.9, Math.PI * 1.7);
826:     ctx.stroke();
827:     const blink = (g.time * 6) % 1 > 0.5;
828:     ctx.fillStyle = blink ? '#ff5a4c' : '#7a221e';
829:     ctx.beginPath();
830:     ctx.arc(0, 0, 2.1, 0, TAU);
