const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
async function fps(page, ms = 2000) {
  return page.evaluate((ms) => new Promise((res) => {
    let frames = 0; const t0 = performance.now();
    const tick = () => { frames++; if (performance.now() - t0 < ms) requestAnimationFrame(tick); else res({ fps: frames / ((performance.now() - t0) / 1000), frames, ms: performance.now() - t0 }); };
    requestAnimationFrame(tick);
  }), ms);
}
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR', e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  // hide start screen and start match via game API
  await page.evaluate(() => {
    const g = window.__fortArtillery;
    document.getElementById('startScreen').style.display = 'none';
    g.startMatch();
  });
  await page.waitForTimeout(1200);
  console.log('game fps', await fps(page, 2500));
  console.log('game info', await page.evaluate(() => {
    const g = window.__fortArtillery;
    return { state: g.state, running: g.running, view: g.view, dpr: g.view.dpr, canvas: [g.canvas.width, g.canvas.height] };
  }));
  // Instrument render phases
  const times = await page.evaluate(() => {
    const g = window.__fortArtillery;
    const ctx = g.ctx;
    const res = {};
    const bench = (name, fn) => { const t = performance.now(); fn(); ctx.getImageData(0, 0, 1, 1); res[name] = performance.now() - t; };
    bench('render-full', () => g.render());
    bench('render-norender', () => {});
    bench('sky', () => { ctx.setTransform(1,0,0,1,0,0); ctx.drawImage(g.skyCache, 0, 0); ctx.getImageData(0,0,1,1); });
    bench('worldBg', () => { ctx.setTransform(1,0,0,1,0,0); ctx.drawImage(g.worldBg, 0, 0); ctx.getImageData(0,0,1,1); });
    bench('terrain', () => { ctx.setTransform(1,0,0,1,0,0); ctx.drawImage(g.terrain.canvas, 0, 0); ctx.getImageData(0,0,1,1); });
    bench('vignette', () => { ctx.setTransform(1,0,0,1,0,0); ctx.drawImage(g.vignetteCache, 0, 0); ctx.getImageData(0,0,1,1); });
    return res;
  });
  console.log('phase ms', times);
  await page.screenshot({ path: '/tmp/opencode/shots/game-real.png' });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

