const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.addInitScript(() => {
    window.__rafLog = [];
    const raf = window.requestAnimationFrame.bind(window);
    let last = performance.now();
    window.requestAnimationFrame = (cb) => raf((t) => {
      const s = performance.now();
      try { cb(t); } finally {
        const now = performance.now();
        window.__rafLog.push({ start: Math.round(s), dur: Math.round(now - s), gap: Math.round(s - last), now: Math.round(now) });
        if (window.__rafLog.length > 300) window.__rafLog.shift();
        last = now;
      }
    });
    window.__long = [];
    try { new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__long.push({ start: Math.round(e.startTime), dur: Math.round(e.duration) }); }).observe({ entryTypes: ['longtask'] }); } catch {}
  });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  const t0 = Date.now();
  console.log('loaded at', Date.now() - t0);
  await page.locator('body').waitFor({ state: 'visible' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  console.log('fonts loaded at', Date.now() - t0);
  const candidate = page.locator('button, input[type="button"], input[type="submit"], [role="button"]');
  const matches = [];
  for (const control of await candidate.all()) {
    if (!await control.isVisible() || !await control.isEnabled()) continue;
    const eligible = await control.evaluate((element) => {
      if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false;
      return /^(?:start|play)(?:\s+(?:game|now))?$/i.test((element.getAttribute('aria-label') || element.value || element.textContent || '').trim());
    });
    if (eligible) matches.push(control);
  }
  console.log('matches at', Date.now() - t0, matches.length);
  const s = Date.now();
  try { await matches[0].click({ trial: true, timeout: 2000 }); console.log('trial ok after', Date.now() - s, 'at', Date.now() - t0); }
  catch (e) {
    console.log('trial fail after', Date.now() - s, 'at', Date.now() - t0, e.message.split('\n').slice(4, 8).join(' | '));
    const log = await page.evaluate(() => window.__rafLog.slice(-20));
    const long = await page.evaluate(() => window.__long.slice(-20));
    console.log('raf', JSON.stringify(log));
    console.log('long', JSON.stringify(long));
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

