    justButton: '.start-inner>*:not(.logo-lockup){display:none!important} .logo-lockup{display:none!important}',
  };
  for (const [name, css] of Object.entries(variants)) {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
    if (css) await page.addStyleTag({ content: css });
    await page.waitForLoadState('load');
    await page.waitForFunction(() => document.fonts.status === 'loaded');
    const s = Date.now();
    try { await page.locator('#playBtn').click({ trial: true, timeout: 8000 }); console.log(name, 'trial ok', Date.now() - s); }
    catch (e) { console.log(name, 'trial fail', Date.now() - s); }
    await page.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

const { createRequire } = require('node:module');
