if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
async function test(name, warm) {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  if (warm) await page.addInitScript(() => {
    const t = performance.now();
    const c = document.createElement('canvas');
    c.width = 8; c.height = 8;
    const gl = c.getContext('webgl2') || c.getContext('webgl');
    if (gl) {
      const vs = gl.createShader(gl.VERTEX_SHADER);
      gl.shaderSource(vs, 'attribute vec2 p; void main(){gl_Position=vec4(p,0.,1.);}');
      gl.compileShader(vs);
      const fs = gl.createShader(gl.FRAGMENT_SHADER);
      gl.shaderSource(fs, 'precision mediump float; void main(){gl_FragColor=vec4(1.,0.,0.,1.);}');
      gl.compileShader(fs);
      const prog = gl.createProgram();
      gl.attachShader(prog, vs); gl.attachShader(prog, fs); gl.linkProgram(prog); gl.useProgram(prog);
      const buf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1,3,-1,-1,3]), gl.STATIC_DRAW);
      const loc = gl.getAttribLocation(prog, 'p');
      gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      gl.finish();
      gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array(4));
    }
    document.title = 'warm ' + Math.round(performance.now() - t);
  });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  const title = await page.title();
  const s = Date.now();
  let result;
  try { await page.locator('#playBtn').click({ trial: true, timeout: 8000 }); result = 'ok ' + (Date.now() - s); }
  catch (e) { result = 'fail ' + (Date.now() - s); }
  console.log(name, title, result);
  await browser.close();
}
(async () => {
  await test('no-warm', false);
  await test('warm', true);
})().catch(e => { console.error(e); process.exit(1); });

