(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.evaluate(() => {
    window.__samples = [];
    window.__rafs = [];
    const t0 = performance.now();
    const raf = window.requestAnimationFrame.bind(window);
    const tick = () => { window.__rafs.push(Math.round(performance.now() - t0)); raf(tick); };
    raf(tick);
    const el = document.getElementById('playBtn');
    setInterval(() => {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      window.__samples.push({ t: Math.round(performance.now() - t0), x: r.x, y: r.y, w: r.width, h: r.height, tf: cs.transform, anims: document.getAnimations().filter(a => a.playState === 'running').map(a => a.animationName) });
    }, 250);
  });
  await page.waitForTimeout(7500);
  const out = await page.evaluate(() => ({ samples: window.__samples, rafs: window.__rafs }));
  console.log('rafs', out.rafs);
  console.log('samples', JSON.stringify(out.samples, null, 1));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

