const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(300);
  const result = await page.evaluate(async () => {
    const g = window.__fortArtillery;
    const log = [];
    const step = (n, dt = 1 / 60) => { for (let i = 0; i < n; i++) g.update(dt); };
    g.startMatch();
    g.running = false;
    step(30);
    log.push(['start', g.state, g.active.name, Math.round(g.active.x), Math.round(g.active.y), g.worms.map(w => [w.name, Math.round(w.x), Math.round(w.y)])]);

    // movement
    const x0 = g.active.x;
    g.keys.right = true; step(30); g.keys.right = false;
    const x1 = g.active.x;
    log.push(['move', Math.round(x1 - x0), Math.round(g.moveLeft)]);

    // jump
    g.jump(); log.push(['jump', g.active.grounded, Math.round(g.active.vy)]); step(60);
    log.push(['landed', g.active.grounded]);

    // build a wall near the worm
    g.teams[0].mats = 180;
    g.toggleBuild(true); g.setBuildType('wall');
    const bx = g.active.x + 110;
    g.placeCurrentBuild({ x: bx, y: g.active.y - 20 });
    log.push(['build', g.buildings.length, g.teams[0].mats, g.buildsUsed]);
    g.toggleBuild(false);

    // fire and resolve
    g.aim.angle = 55; g.aim.power = 72;
    const beforeMat = JSON.stringify(g.terrain.mask.slice(0, 0));
    const shots0 = g.stats.shots;
    g.sound.setMuted(true);
    const fired = (await import('./js/actions.js')).fire(g);
    log.push(['fire', fired, g.state, g.projectiles.length, g.stats.shots - shots0]);
    step(900);
    log.push(['after fire', g.state, g.turnTeam, g.active?.name, g.worms.map(w => [w.name, w.alive, Math.round(w.health)]), g.buildings.length, !!g.lastExplosion]);

    // Let the AI take its turn
    const aiStart = g.state;
    step(1200);
    log.push(['after AI', aiStart, '->', g.state, g.turnTeam, g.active?.name, g.worms.map(w => [w.name, w.alive, Math.round(w.health)]), g.stats.shots]);

    // llama loot
    const llama = g.llamas.find(l => l.alive);
    if (llama) {
      const before = g.teams[0].mats;
      (await import('./js/actions.js')).damageLlama(g, llama, 999, 0);
      log.push(['llama', llama.alive, before, g.teams[0].mats]);
    }

    // grenade preview bounce check: place a wall in front and simulate
    const phys = await import('./js/physics.js');
    const cfg = (await import('./js/config.js')).WEAPONS[1];
    g.teams[0].mats = 180; g.buildsUsed = 0; g.toggleBuild(true); g.setBuildType('wall');
    g.placeCurrentBuild({ x: g.active.x + 120, y: g.active.y - 60 });
    g.toggleBuild(false);
    const pv = phys.simulateTrajectory(g, g.active, 45, 55, cfg, true);
    log.push(['grenade preview', pv.pts.length, pv.blocked, pv.end]);

    return { log, state: g.state, errors: [] };
  });
  console.log(JSON.stringify(result.log, null, 1));
  console.log('page errors', errors);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

