const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(300);

  const phase1 = await page.evaluate(async () => {
    const g = window.__fortArtillery;
    const log = [];
    const step = (n, dt = 1 / 60) => { for (let i = 0; i < n; i++) g.update(dt); };
    const actions = await import('./js/actions.js');
    const phys = await import('./js/physics.js');
    const { WEAPONS } = await import('./js/config.js');

    g.startMatch();
    g.running = false;
    g.sound.setMuted(true);
    step(30);
    log.push(['start', g.state, g.active.name, g.worms.filter(w => w.alive).length, g.worms.every(w => w.grounded)]);

    // --- weapon selection + ammo spend ---
    g.selectWeapon(1);
    const ammoBefore = g.active.ammo.grenade;
    g.aim.angle = 62; g.aim.power = 70;
    const fired = actions.fire(g);
    log.push(['grenade fire', fired, g.state, g.active.ammo.grenade, ammoBefore, g.projectiles.length]);
    step(1200);
    log.push(['grenade resolved', g.state, g.turnTeam, g.active.name, g.lastExplosion != null]);

    // --- building damage/destruction + debris ---
    g.teams[0].mats = 180; g.buildsUsed = 0;
    g.toggleBuild(true); g.setBuildType('wall');
    const wallX = Math.min(1450, g.active.x + 100);
    g.placeCurrentBuild({ x: wallX, y: g.active.y - 40 });
    g.toggleBuild(false);
    const wall = g.buildings[g.buildings.length - 1];
    const wallHp = wall?.hp;
    const partsBefore = g.particles.length;
    if (wall) actions.damageBuilding(g, wall, 999);
    log.push(['building destroyed', !!wall, wallHp, wall?.destroyed, wall?.hp, g.particles.length > partsBefore]);
    // explosion filter removes destroyed buildings
    g.buildings = g.buildings.filter((b) => b.hp > 0);
    log.push(['building filtered', g.buildings.filter(b => b.destroyed).length]);

    // --- llama loot below cap and at cap ---
    const llama = g.llamas.find((l) => l.alive);
    g.teams[0].mats = 100;
    if (llama) actions.damageLlama(g, llama, 999, 0);
    log.push(['llama below cap', llama ? [llama.alive, g.teams[0].mats, g.stats.llamas] : 'none']);
    const llama2 = g.llamas.find((l) => l.alive);
    g.teams[0].mats = 170;
    const matsBefore2 = g.teams[0].mats;
    if (llama2) actions.damageLlama(g, llama2, 999, 0);
    log.push(['llama cap', llama2 ? [matsBefore2, g.teams[0].mats, g.stats.llamas] : 'none']);

    // --- grenade preview bounces off a building ---
    g.teams[0].mats = 180; g.buildsUsed = 0;
    g.toggleBuild(true); g.setBuildType('wall');
    g.placeCurrentBuild({ x: g.active.x + 150, y: g.active.y - 80 });
    g.toggleBuild(false);
    const pv = phys.simulateTrajectory(g, g.active, 45, 65, WEAPONS[1], true);
    log.push(['grenade preview', pv.pts.length, pv.blocked, pv.bounces, pv.hitBuilding !== null]);

    // --- AI turn: plan and shoot ---
    g.state = 'aim';
    g.turnTeam = 0;
    g.checkGameOver();
    g.finishTurn(); // hand over to rival
    log.push(['to AI', g.state, g.turnTeam, g.active.name]);
    step(240);
    log.push(['AI plan', g.aiStage, !!g.aiPlan, g.aiPlan?.angle, g.aiPlan?.power, g.selectedWeapon]);
    const aiShots = g.stats.shots;
    g.aiTimer = 0;
    step(600);
    log.push(['AI resolved', g.state, g.turnTeam, g.stats.shots > aiShots, g.worms.map(w => [w.name, w.alive, Math.round(w.health)])]);

    // --- damage worm kills and game over ---
    for (const w of g.worms.filter((w) => w.team === 1)) actions.killWorm(g, w);
    const over = g.checkGameOver();
    log.push(['victory', over, g.state, document.getElementById('resultTitle').textContent, document.getElementById('resultKicker').textContent]);
    return log;
  });

  await page.waitForTimeout(1300);
  const resultVisible = await page.evaluate(() => {
    const g = window.__fortArtillery;
    const el = document.getElementById('gameOver');
    return {
      hidden: el.classList.contains('is-hidden'),
      title: document.getElementById('resultTitle').textContent,
      stats: document.getElementById('resultStats').textContent.replace(/\s+/g, ' ').trim(),
      overlayDisplay: getComputedStyle(el).display,
      state: g.state,
      shots: g.stats.shots,
    };
  });

  // Click play again via the real button.
  await page.click('#againBtn');
  await page.waitForTimeout(500);
  const phase2 = await page.evaluate(() => {
    const g = window.__fortArtillery;
    return {
      state: g.state,
      running: g.running,
      active: g.active?.name,
      alive: g.worms.filter((w) => w.alive).length,
      hp: g.worms.map((w) => w.health),
      buildings: g.buildings.length,
      llamas: g.llamas.length,
      resultHidden: document.getElementById('gameOver').classList.contains('is-hidden'),
      hudVisible: !document.getElementById('hud').classList.contains('is-hidden'),
    };
  });

  // Loss + draw copy, then a clean restart.
  const phase3 = await page.evaluate(() => {
    const g = window.__fortArtillery;
    g.running = false;
    const out = {};
    g.endMatch(1);
    out.loss = [g.state, document.getElementById('resultKicker').textContent, document.getElementById('resultTitle').textContent];
    g.state = 'aim'; g.startMatch(); g.running = false;
    g.endMatch(null);
    out.draw = [g.state, document.getElementById('resultKicker').textContent, document.getElementById('resultTitle').textContent];
    g.startMatch(); g.running = false;
    out.restart = [g.state, g.active.name, g.worms.every((w) => w.health === 100 && w.alive)];
    return out;
  });

  console.log(JSON.stringify({ phase1, resultVisible, phase2, phase3, errors }, null, 1));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

