  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(300);
  const out = await page.evaluate(async () => {
    const g = window.__fortArtillery;
    const { BUILDS, GRID, WORM_R } = await import('./js/config.js');
    g.startMatch(); g.running = false; g.sound.setMuted(true);
    for (let i = 0; i < 30; i++) g.update(1/60);
    const W = 1500, H = 900;
    function chk(type, wx, wy, clr, maxSolid) {
      const cfg = BUILDS[type];
      const gx = Math.round((wx - GRID/2)/GRID)*GRID + GRID/2;
      const gy = Math.round((wy - GRID/2)/GRID)*GRID + GRID/2;
      const x = gx - cfg.w/2, y = gy - cfg.h/2;
      if (x < 12 || x+cfg.w > W-12 || y < 64 || y+cfg.h > H-8) return false;
      const a = g.active;
      if (a && Math.hypot(gx-a.x, gy-a.y) > 250) return false;
      let solid = 0;
      for (let iy=0; iy<4; iy++) for (let ix=0; ix<4; ix++) {
        if (g.terrain.solidAt(x+((ix+.5)/4)*cfg.w, y+((iy+.5)/4)*cfg.h)) solid++;
      }
      if (solid/16 > maxSolid) return false;
      for (const w of g.worms) {
        if (!w.alive) continue;
        const nx = Math.max(x, Math.min(w.x, x+cfg.w));
        const ny = Math.max(y, Math.min(w.y, y+cfg.h));
        if (Math.hypot(w.x-nx, w.y-ny) < WORM_R + clr) return false;
      }
      return true;
    }
    const results = [];
    for (const w of g.worms.filter(w=>w.team===0)) {
      for (const type of ['wall','floor','ramp']) {
        const row = { worm: w.name, type };
        for (const [clr,maxSolid] of [[4,.42],[2,.42],[0,.42],[-4,.42],[2,.5],[2,.55],[0,.55],[-4,.55],[0,.6]]) {
          let count = 0, near = 0;
          for (let dx=-180; dx<=180; dx+=20) for (let dy=-140; dy<=80; dy+=20) {
            if (chk(type, w.x+dx, w.y+dy, clr, maxSolid)) { count++; if (Math.abs(dx)<=100 && dy<=20 && dy>=-80) near++; }
          }
          row[`c${clr}_s${maxSolid}`] = [count, near];
        }
        results.push(row);
      }
    }
    return results;
  });
  console.log(JSON.stringify(out, null, 1));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
