const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(300);

  const out = await page.evaluate(async () => {
    const g = window.__fortArtillery;
    const log = [];
    const step = (n, dt = 1 / 60) => { for (let i = 0; i < n; i++) g.update(dt); };
    const actions = await import('./js/actions.js');
    const phys = await import('./js/physics.js');
    const build = await import('./js/build.js');
    const { WEAPONS, BUILDS } = await import('./js/config.js');

    g.startMatch();
    g.running = false;
    g.sound.setMuted(true);
    step(30);
    g.teams[0].mats = 180;

    // Find a valid wall placement near the active worm.
    let spot = null;
    outer: for (const dx of [90, 120, 60, 150, 180, -90, -120]) {
      for (const dy of [-40, -70, -100, 20, 50, -10]) {
        const p = phys.computePlacement(g, 'wall', g.active.x + dx, g.active.y + dy, 0);
        if (p.valid) { spot = p; break outer; }
      }
    }
    const placed = spot ? build.placeBuild(g, 'wall', spot.cx, spot.cy, 0, true) : false;
    const wall = g.buildings[g.buildings.length - 1];
    log.push(['wall placed', placed, g.buildings.length, wall ? [Math.round(wall.x), Math.round(wall.y), wall.hp] : null, g.teams[0].mats, g.buildsUsed]);

    // Destructible building via an explosion.
    const parts0 = g.particles.length;
    if (wall) actions.explode(g, wall.x + wall.w / 2, wall.y + wall.h / 2, BUILDS.wall.w, 999, 0, g.active, WEAPONS[0]);
    log.push(['wall blasted', g.buildings.includes(wall), wall?.destroyed, wall?.hp, g.particles.length > parts0]);

    // Terrain destruction: count solid pixels in a small block before/after a blast.
    const cx = g.active.x + 130;
    const cy = g.terrain.surfaceBelow(cx, 200, 900) + 40;
    let before = 0;
    for (let y = cy - 36; y <= cy + 36; y += 6) for (let x = cx - 36; x <= cx + 36; x += 6) if (g.terrain.solidAt(x, y)) before++;
    actions.explode(g, cx, cy, 90, 0, 0, g.active, WEAPONS[0]);
    let after = 0;
    for (let y = cy - 36; y <= cy + 36; y += 6) for (let x = cx - 36; x <= cx + 36; x += 6) if (g.terrain.solidAt(x, y)) after++;
    log.push(['terrain carved', before, after, after < before]);

    // Real building collision: fire a grenade horizontally into a wall and count bounces.
    g.state = 'aim';
    g.teams[0].mats = 180;
    g.buildsUsed = 0;
    g.selectedWeapon = 1;
    const bwall = {
      type: 'wall',
      x: g.active.x + 95,
      y: g.active.y - 90,
      w: 72, h: 72, dir: 1, team: 0, hp: 120, maxHp: 120,
      born: g.time, seed: 1, hit: 0,
    };
    g.buildings.push(bwall);
    g.active.ammo.grenade = 3;
    g.aim.angle = 18;
    g.aim.power = 55;
    const fired = actions.fire(g);
    let maxBounces = 0;
    for (let i = 0; i < 1400; i++) {
      g.update(1 / 60);
      for (const p of g.projectiles) maxBounces = Math.max(maxBounces, p.bounces);
      if (g.state !== 'flying') break;
    }
    log.push(['grenade wall bounce', fired, maxBounces, g.state, g.buildings.includes(bwall), bwall.hp]);

    // Weapon switching via UI click and ammo fallback.
    g.state = 'aim'; g.turnTeam = 0; g.active = g.worms.find(w => w.team === 0 && w.alive);
    g.active.ammo.grenade = 3;
    document.querySelectorAll('.weapon-btn')[1].click();
    const uiSel = g.selectedWeapon;
    g.active.ammo.grenade = 0;
    document.querySelectorAll('.weapon-btn')[1].click();
    log.push(['weapon UI', uiSel, g.selectedWeapon, document.querySelectorAll('.weapon-btn')[1].disabled]);
    g.selectWeapon(2);
    const cluster = g.selectedWeapon;
    g.active.ammo.cluster = 0;
    g.selectWeapon(2);
    log.push(['weapon ammo guard', cluster, g.selectedWeapon]);

    // Llama loot should cap at 180 and credit the shooting team.
    g.teams[1].mats = 100;
    const llama = g.llamas.find(l => l.alive);
    if (llama) actions.damageLlama(g, llama, 999, 1);
    log.push(['llama team cap', g.teams[1].mats, g.teams[0].mats, g.stats.llamas]);

    return log;
  });
  console.log(JSON.stringify({ out, errors }, null, 1));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

