const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  for (const vp of [{width:1440,height:900},{width:390,height:844},{width:360,height:640},{width:844,height:390}]) {
    const page = await browser.newPage({ viewport: vp });
    await page.goto('http://localhost:3002', { waitUntil: 'load' });
    await page.waitForTimeout(250);
    await page.evaluate(() => window.__fortArtillery.startMatch());
    await page.waitForTimeout(250);
    const r = await page.evaluate(() => {
      const rect = (sel) => { const e = document.querySelector(sel); if (!e) return null; const b=e.getBoundingClientRect(); return {t:Math.round(b.top),b:Math.round(b.bottom),l:Math.round(b.left),r:Math.round(b.right),h:Math.round(b.height),display:getComputedStyle(e).display}; };
      return {
        vp: [innerWidth, innerHeight],
        hud: rect('#hud'), topbar: rect('.topbar'), dock: rect('.dock'), hints: rect('.dock-hints'), weapons: rect('.weapon-bar'), controls: rect('.dock-controls'), fire: rect('#fireBtn'), rotate: rect('#rotateHint'), banner: rect('#banner'), target: rect('#targetChip'),
        hintText: document.querySelector('.dock-hints')?.textContent.replace(/\s+/g,' ').trim(),
      };
    });
    console.log(JSON.stringify(r));
    await page.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
EOF
