cat > /tmp/opencode/soak.cjs <<'EOF'
const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(300);
  const out = await page.evaluate(async () => {
    const g = window.__fortArtillery;
    const { fire } = await import('./js/actions.js');
    const { planAI } = await import('./js/ai.js');
    g.startMatch();
    g.running = false;
    g.sound.setMuted(true);
    let guard = 0;
    let playerShots = 0;
    let aiShots = 0;
    let turns = 1;
    let lastTurn = g.turnTeam;
    const seen = new Set();
    while (g.state !== 'over' && guard < 60 * 60 * 12) {
      guard++;
      if (g.state === 'aim') {
        const plan = planAI(g);
        if (plan) {
          g.selectedWeapon = plan.weaponIndex;
          g.aim.angle = plan.angle;
          g.aim.power = plan.power;
          if (fire(g)) playerShots++;
        } else {
          g.finishTurn();
        }
      }
      g.update(1 / 60);
      if (g.turnTeam !== lastTurn) { turns++; lastTurn = g.turnTeam; }
      seen.add(g.state);
    }
    const stats = {
      guard, finished: g.state === 'over', turns, playerShots, aiShots: g.stats.shots - playerShots,
      totalShots: g.stats.shots + (g.stats.shots - playerShots), statsShots: g.stats.shots,
      result: document.getElementById('resultTitle').textContent,
      kicker: document.getElementById('resultKicker').textContent,
      worms: g.worms.map(w => [w.name, w.alive, Math.round(w.health)]),
      damageDealt: Math.round(g.stats.damage), damageTaken: Math.round(g.stats.taken),
      llamasLooted: g.stats.llamas, buildings: g.buildings.length, builds: g.stats.builds,
      states: [...seen], infinite: g.worms.some(w => !Number.isFinite(w.x) || !Number.isFinite(w.y)),
      outOfBounds: g.worms.filter(w => w.alive && (w.x < 0 || w.x > 1500 || w.y < -200 || w.y > 1000)).map(w => w.name),
      consoleErrors: [],
    };
    return stats;
  });
  console.log(JSON.stringify({ out, errors }, null, 1));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
EOF
