  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(500);
  const back = await page.evaluate(() => { const g=window.__fortArtillery; return { scale:g.view.scale, cam:[Math.round(g.camX),Math.round(g.camY)], canvas:[g.canvas.width,g.canvas.height], state:g.state }; });
  console.log(JSON.stringify({ before, after, back, errors }, null, 1));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
